const std = @import("std");
const mem = std.mem;
const ascii = std.ascii;

pub const AffineCipherError = error{
    NotCoprime,
};

/// Helper: check if a and m are coprime (m is 26)
fn areCoprime(a: u8, m: u8) bool {
    return gcd(a, m) == 1;
}

fn gcd(a: u8, b: u8) u8 {
    var x = a;
    var y = b;
    while (y != 0) {
        const t = y;
        y = x % y;
        x = t;
    }
    return x;
}

/// Compute modular multiplicative inverse of a modulo m (m=26). Assumes a and m are coprime.
fn modInverse(a: u8, m: u8) u8 {
    // Extended Euclidean algorithm
    var m0: u32 = m;
    var a0: u32 = a;
    var t: u32 = 0;
    var q: u32 = 0;
    var x0: u32 = 1;
    var x1: u32 = 0;

    while (a0 != 0) {
        q = m0 / a0;
        t = a0;
        a0 = m0 - q * a0;
        m0 = t;

        t = x0;
        x0 = x1 - q * x0;
        x1 = t;
    }

    // x1 is the inverse modulo m
    return @intCast(x1 % m);
}
```

But we need to be careful: the extended Euclidean algorithm returns the inverse modulo m, but we need to ensure it's positive. The algorithm above is typical for finding inverse of a modulo m. However, we can also just loop.

