fn gcd(a: u8, b: u8) u8 {
    var x = a;
    var y = b;
    while (y != 0) {
        const t = y;
        y = x % y;
        x = t;
    }
    return x;
}

fn areCoprime(a: u8, m: u8) bool {
    return gcd(a, m) == 1;
}

fn modInverse(a: u8, m: u8) u8 {
    // a and m must be coprime
    for (1..m) |x| {
        if ((a * @intCast(x)) % m == 1) {
            return @intCast(x);
        }
    }
    // Should never happen if a and m are coprime
    @panic("No modular inverse");
}
