pub fn encode(allocator: mem.Allocator, phrase: []const u8, a: u8, b: u8) (mem.Allocator.Error || AffineCipherError)![]u8 {
    const a_mod = a % 26;
    const b_mod = b % 26;
    if (!areCoprime(a_mod, 26)) {
        return error.NotCoprime;
    }

    var list = std.ArrayList(u8).init(allocator);
    defer list.deinit();

    for (phrase) |c| {
        if (ascii.isDigit(c)) {
            try list.append(c);
        } else if (ascii.isAlphabetic(c)) {
            const upper = ascii.toUpper(c);
            const idx = upper - 'A';
            const enc_idx = (a_mod * idx + b_mod) % 26;
            const enc_char = 'a' + enc_idx;
            try list.append(enc_char);
        } else {
            // skip spaces, punctuation, etc.
        }
    }

    const raw = list.items;
    const raw_len = raw.len;

    // Compute groups and spaces
    const groups = (raw_len + 4) / 5; // ceiling division
    const spaces = if (groups > 0) groups - 1 else 0;
    const total_len = raw_len + spaces;

    const buffer = try allocator.alloc(u8, total_len);
    errdefer allocator.free(buffer);

    var idx: usize = 0;
    var group_count: usize = 0;
    for (raw) |ch| {
        buffer[idx] = ch;
        idx += 1;
        group_count += 1;
        if (group_count == 5 and idx < total_len) {
            buffer[idx] = ' ';
            idx += 1;
            group_count = 0;
        }
    }

    return buffer;
}
