pub fn decode(allocator: mem.Allocator, phrase: []const u8, a: u8, b: u8) (mem.Allocator.Error || AffineCipherError)![]u8 {
    const a_mod = a % 26;
    const b_mod = b % 26;
    if (!areCoprime(a_mod, 26)) {
        return error.NotCoprime;
    }

    const inv = modInverse(a_mod, 26);

    var list = std.ArrayList(u8).init(allocator);
    defer list.deinit();

    for (phrase) |c| {
        if (ascii.isDigit(c)) {
            try list.append(c);
        } else if (ascii.isAlphabetic(c)) {
            const upper = ascii.toUpper(c);
            const idx = upper - 'A';
            // Compute (idx - b_mod) mod 26
            const diff = (idx + 26 - b_mod) % 26;
            const dec_idx = (inv * diff) % 26;
            const dec_char = 'a' + dec_idx;
            try list.append(dec_char);
        } else {
            // skip spaces, punctuation
        }
    }

    return try list.toOwnedSlice();
}
